            StageName = 'Prospecting',
            CloseDate = Date.today(),
            Amount = 500
        );

        mocks.startStubbing();
        mocks.when(selectorMock.selectById((Set<Id>) fflib_Match.anyObject()))
            .thenReturn(new List<Opportunity>{ openOpp });
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        RenewalService.createRenewals(new Set<Id>{ oppId });
        Test.stopTest();

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0))
            .registerNew((SObject) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerNew(
            (SObject) fflib_Match.anyObject(),
            (Schema.SObjectField) fflib_Match.anyObject(),
            (SObject) fflib_Match.anyObject()
        );
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @isTest
    static void doesNothingWhenOpportunityIdsIsNullOrEmpty() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        RenewalService.createRenewals(null);
        RenewalService.createRenewals(new Set<Id>());
        Test.stopTest();

        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0))
            .registerNew((SObject) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }
}
