        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
        Application.UnitOfWork.setMock(mockUow);

        Test.startTest();
        Integer resultNull = InvoicingService.invoiceWonOpportunities(null);
        Integer resultEmpty = InvoicingService.invoiceWonOpportunities(new Set<Id>());
        Test.stopTest();

        System.assertEquals(0, resultNull, 'Null input should return 0');
        System.assertEquals(0, resultEmpty, 'Empty input should return 0');

        ((IBillingGateway) mocks.verify(mockGateway, mocks.never())).authenticate();
        ((IOpportunitiesSelector) mocks.verify(mockSelector, mocks.never())).selectById((Set<Id>) fflib_Match.anyObject());
