    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        fflib_QueryFactory qf = newQueryFactory();

        qf.selectField('Account.Name');

        qf.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Descending order on Amount: SOQL's default null handling for
        // DESCENDING puts NULL values last, which satisfies the requirement
        // that opportunities without an Amount come after all others.
        qf.addOrdering(
            new fflib_QueryFactory.Ordering(
                'Opportunity',
                'Amount',
                fflib_QueryFactory.SortOrder.DESCENDING
            )
        );
        qf.addOrdering(
            new fflib_QueryFactory.Ordering(
                'Opportunity',
                'CloseDate',
                fflib_QueryFactory.SortOrder.ASCENDING
            )
        );

        qf.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(qf.toSOQL());
    }
}
