public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        // Only contacts that actually have a phone value are relevant;
        // querying with "Phone != null" effectively leaves out the rest.
        List<Contact> contactsToUpdate = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            AND Phone != null
        ];

        if (contactsToUpdate.isEmpty()) {
            return errorsByContactId;
        }

        for (Contact c : contactsToUpdate) {
            c.Phone = c.Phone.replaceAll('[^0-9+]', '');
        }

        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult sr = saveResults[i];
            if (!sr.isSuccess()) {
                Database.Error firstError = sr.getErrors()[0];
                errorsByContactId.put(contactsToUpdate[i].Id, firstError.getMessage());
            }
        }

        return errorsByContactId;
    }
}
