public with sharing class LineItemDiscountHandler {

    /**
     * For any new OpportunityLineItem without an explicit Discount
     * (null means "not set" - a rep-entered 0 is preserved), apply the
     * standard discount for its product, per the rules owned by PricingRules.
     *
     * PricingRules.standardDiscountFor(Id) runs its own SOQL query against
     * Product2 every time it's called, which is not safe to call once per
     * line (CPQ can send up to 200 lines per opportunity). To keep this
     * trigger bulk-safe regardless of how many lines or distinct products
     * are involved, we resolve all needed Product2.Family values with a
     * single bulk query, then use PricingRules.standardDiscountForFamily(),
     * which is a pure function with no SOQL of its own. This still relies
     * entirely on PricingRules for the actual discount logic - we never
     * duplicate or hardcode the rule values here.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        Set<Id> productIdsNeedingDiscount = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        Map<Id, Decimal> standardDiscountByProductId = new Map<Id, Decimal>();

        // Single bulk query, regardless of how many distinct products are involved.
        for (Product2 product : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIdsNeedingDiscount
        ]) {
            standardDiscountByProductId.put(
                product.Id,
                PricingRules.standardDiscountForFamily(product.Family)
            );
        }

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                Decimal standardDiscount = standardDiscountByProductId.get(line.Product2Id);
                if (standardDiscount != null) {
                    line.Discount = standardDiscount;
                }
            }
        }
    }
}
