/**
 * After-update trigger on Case.
 *
 * For every case that transitions from not-closed to closed, we kick off a
 * CaseSurveyJob (Queueable) that creates a CSAT survey Task. Each case gets
 * its own job execution whenever possible, so that a failure on one case
 * never affects another.
 *
 * System.enqueueJob can be called at most 50 times per Apex transaction
 * (Limits.getLimitQueueableJobs()). Agents can bulk-close from list views
 * and a nightly API job can close up to 200 cases in a single DML statement
 * / single trigger invocation, so calling enqueueJob once per case directly
 * is not always possible without breaching that limit. We handle this as
 * follows:
 *
 *   - If the whole batch fits in the jobs still available this transaction,
 *     we enqueue one CaseSurveyJob per case directly (the simple, requested
 *     behaviour, and the normal path for everyday case closing).
 *   - Otherwise we use up the remaining slots for individual cases and hand
 *     the rest to a single "overflow" CaseSurveyJob that processes all of
 *     those remaining cases in one execution (see CaseSurveyJob for how
 *     per-case isolation is still preserved there). We deliberately do NOT
 *     have that overflow job chain itself via further System.enqueueJob
 *     calls: Queueable chaining is restricted to a single level of depth in
 *     test context (Test.startTest/stopTest), so recursively re-enqueuing
 *     for a 200-case batch throws "Maximum stack depth has been reached".
 *     Processing the whole remainder in one loop avoids that entirely while
 *     still respecting the 50-jobs-per-transaction governor limit.
 */
trigger CaseTrigger on Case (after update) {

    List<Id> closedCaseIds = new List<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);
        if (newCase.IsClosed && !oldCase.IsClosed) {
            closedCaseIds.add(newCase.Id);
        }
    }

    if (closedCaseIds.isEmpty()) {
        return;
    }

    Integer jobLimit = Limits.getLimitQueueableJobs();
    Integer jobsUsed = Limits.getQueueableJobs();
    Integer availableSlots = jobLimit - jobsUsed;

    if (availableSlots <= 0) {
        // No room left in this transaction to enqueue anything further
        // (e.g. other automation already used up the allowance). There is
        // nothing safe we can do here without risking a LimitException.
        return;
    }

    if (closedCaseIds.size() <= availableSlots) {
        // Plenty of room: one job per case, exactly as specified.
        for (Id caseId : closedCaseIds) {
            System.enqueueJob(new CaseSurveyJob(caseId));
        }
        return;
    }

    // Not enough room for one job per case in this single transaction.
    // Use all but one of the remaining slots directly...
    Integer directSlots = availableSlots - 1;
    for (Integer i = 0; i < directSlots; i++) {
        System.enqueueJob(new CaseSurveyJob(closedCaseIds[i]));
    }

    // ...and hand the remainder to a single job that processes all of them
    // in one execution (no further chaining - see CaseSurveyJob).
    List<Id> remaining = new List<Id>();
    for (Integer i = directSlots; i < closedCaseIds.size(); i++) {
        remaining.add(closedCaseIds[i]);
    }
    System.enqueueJob(new CaseSurveyJob(remaining));
}
