/**
 * Queueable job that creates CSAT survey Tasks for closed Cases.
 *
 * Usage patterns:
 *   - new CaseSurveyJob(caseId): the normal, common path - one job handles
 *     exactly one case, so a failure for that case cannot affect any other
 *     case's survey Task.
 *   - new CaseSurveyJob(caseIds): an "overflow" path used only when the
 *     trigger has more newly-closed cases in a single transaction than it
 *     can afford individual System.enqueueJob calls for (e.g. the 200-case
 *     nightly API cleanup). This job processes every case in the list
 *     within a single execute() call.
 *
 * We deliberately do NOT chain this job to itself (i.e. execute() never
 * calls System.enqueueJob). Queueable chaining depth is restricted to a
 * single level in test context (Test.startTest/stopTest), so recursively
 * re-enqueuing for a large batch throws
 * "System.AsyncException: Maximum stack depth has been reached". Looping
 * over the whole remaining list in one execution avoids that problem
 * entirely and is well within governor limits (SOQL/DML on up to a couple
 * hundred records is trivial).
 *
 * For the multi-case (overflow) path, per-case isolation is preserved at
 * the DML level: Task records are inserted with Database.insert(..., false)
 * (allOrNone = false), so a problem creating the Task for one case (e.g. a
 * validation rule) cannot prevent the Tasks for the other cases in the same
 * batch from being created.
 *
 * "without sharing" is intentional: this is a system-level background
 * process that should reliably create the survey Task whenever a case is
 * closed, regardless of the record access of whichever user or API
 * integration closed the case.
 */
public without sharing class CaseSurveyJob implements Queueable {

    private final List<Id> caseIds;

    /** Standard entry point: one job for exactly one case. */
    public CaseSurveyJob(Id caseId) {
        this(new List<Id>{ caseId });
    }

    /**
     * Overflow entry point: this job processes every case in the list
     * within a single execution (no chaining).
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        Map<Id, Case> casesById = new Map<Id, Case>([
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
        ]);

        List<Task> tasksToInsert = new List<Task>();

        for (Id caseId : caseIds) {
            Case c = casesById.get(caseId);

            if (c == null || c.ContactId == null) {
                // No contact on the case (or case no longer found): per
                // spec, no survey task is created for it.
                continue;
            }

            tasksToInsert.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            // allOrNone = false keeps cases isolated from each other even
            // when several are processed in the same job execution: one
            // bad record doesn't block the rest from being inserted.
            Database.insert(tasksToInsert, false);
        }
    }
}
