/**
 * Service class used by the peer-to-peer fundraising integration to grant NPSP
 * partial soft credits to fundraisers for gifts they bring in.
 *
 * Declared "without sharing" because this is a backend integration service that
 * must be able to create/maintain Opportunity Contact Roles and Partial Soft
 * Credits regardless of the running user's record-level sharing access. All DML
 * is additionally executed with AccessLevel.SYSTEM_MODE so that the operation
 * is not blocked by the running user's object/field level permissions either.
 */
public without sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null || String.isBlank(req.role)) {
                throw new SoftCreditException('Each request requires an opportunityId, a contactId and a role.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // Query 1 of 4: Opportunities needed to validate primary contact and amount.
        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // Validate the whole call before any DML takes place.
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact on opportunity ' +
                    req.opportunityId + ' and cannot also receive a partial soft credit.'
                );
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive number.');
            }
            Decimal oppAmount = opp.Amount == null ? 0 : opp.Amount;
            if (req.amount > oppAmount) {
                throw new SoftCreditException(
                    'Soft credit amount of ' + req.amount + ' exceeds opportunity amount of ' + oppAmount +
                    ' for opportunity ' + req.opportunityId
                );
            }
        }

        // Query 2 of 4: existing Opportunity Contact Roles for the involved opportunities/contacts.
        // Keyed only by opportunity + contact: a contact must end up with exactly one contact
        // role on the opportunity, so any pre-existing role (e.g. NPSP's "Household Member"
        // role) is reused and renamed rather than leaving a second role behind.
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];

        Map<String, OpportunityContactRole> ocrByPair = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrByPair.containsKey(key)) {
                ocrByPair.put(key, ocr);
            }
        }

        // Query 3 of 4: existing partial soft credits for the involved opportunities/contacts.
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];

        Map<String, npsp__Partial_Soft_Credit__c> pscByPair = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            pscByPair.put(pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c), psc);
        }

        // Work out which Opportunity Contact Roles need to be created or renamed.
        List<OpportunityContactRole> ocrToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrToUpdate = new List<OpportunityContactRole>();
        Set<Id> ocrUpdateIdsSeen = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            OpportunityContactRole existing = ocrByPair.get(key);

            if (existing == null) {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrToInsert.add(newOcr);
                // Store the same reference so the Id populated by the insert below is visible here.
                ocrByPair.put(key, newOcr);
            } else if (existing.Role != req.role) {
                existing.Role = req.role;
                if (!ocrUpdateIdsSeen.contains(existing.Id)) {
                    ocrUpdateIdsSeen.add(existing.Id);
                    ocrToUpdate.add(existing);
                }
            }
        }

        if (!ocrToInsert.isEmpty()) {
            Database.insert(ocrToInsert, AccessLevel.SYSTEM_MODE); // DML 1 of up to 4
        }
        if (!ocrToUpdate.isEmpty()) {
            Database.update(ocrToUpdate, AccessLevel.SYSTEM_MODE); // DML 2 of up to 4
        }

        // Build the partial soft credit inserts/updates, linking to the (now resolved) contact role.
        List<npsp__Partial_Soft_Credit__c> pscToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            OpportunityContactRole ocr = ocrByPair.get(key);

            npsp__Partial_Soft_Credit__c existingPsc = pscByPair.get(key);
            if (existingPsc != null) {
                existingPsc.npsp__Amount__c = req.amount;
                existingPsc.npsp__Role_Name__c = req.role;
                existingPsc.npsp__Contact_Role_ID__c = ocr.Id;
                pscToUpdate.add(existingPsc);
            } else {
                pscToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                ));
            }
        }

        if (!pscToInsert.isEmpty()) {
            Database.insert(pscToInsert, AccessLevel.SYSTEM_MODE); // DML 3 of up to 4
        }
        if (!pscToUpdate.isEmpty()) {
            Database.update(pscToUpdate, AccessLevel.SYSTEM_MODE); // DML 4 of up to 4
        }
    }

    private static String pairKey(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '|' + String.valueOf(contactId);
    }
}
