/**
 * Service class responsible for reassigning ownership of Accounts and their
 * related Contacts to a new owner (e.g. when a book of business moves
 * between sales reps).
 *
 * Account trigger automation (Trigger Actions Framework) is bypassed for the
 * Account update since territory recalculation and other Account-side
 * actions are unnecessary and expensive for a pure ownership change. Contact
 * automation is left untouched and runs normally.
 */
public with sharing class AccountOwnershipService {

    /**
     * Reassigns the given Accounts, and all Contacts related to those
     * Accounts, to the new owner.
     *
     * - Account trigger actions (TAF) are bypassed for the duration of this
     *   call only; the bypass is always cleared afterwards, even if an
     *   exception occurs, so Account automation behaves normally for the
     *   rest of the transaction.
     * - Contact trigger actions run normally.
     * - DML is all-or-none; any exception propagates to the caller unchanged.
     * - Bulk-safe: exactly one SOQL query (for the related Contacts) and two
     *   DML statements (one for Accounts, one for Contacts) regardless of
     *   the number of Accounts passed in (up to governor limits on record
     *   counts, e.g. 200 Accounts per call as documented).
     *
     * @param accountIds the Ids of the Accounts to reassign
     * @param newOwnerId the Id of the new owner (User or Queue, as applicable)
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        TriggerBase.bypass(Account.SObjectType);
        try {
            // Build Account updates directly from the Id set - no need to
            // query Accounts just to set OwnerId.
            // NOTE: do NOT use the List<Account>(Integer size) constructor -
            // in Apex that pre-fills the list with that many null elements
            // (unlike Java's ArrayList), which would cause a
            // "DML statement found null SObject" error once real records
            // are appended via add().
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accountId : accountIds) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
            update accountsToUpdate;

            // Single SOQL query to retrieve all related Contacts.
            List<Contact> contactsToUpdate = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            for (Contact con : contactsToUpdate) {
                con.OwnerId = newOwnerId;
            }

            // Contact trigger actions run normally for this DML.
            update contactsToUpdate;
        } finally {
            // Always restore normal Account automation, success or failure.
            TriggerBase.clearBypass(Account.SObjectType);
        }
    }
}
